char** _multi_string_alloc_and_copy(const char* const* source, size_t count) {
    char** destination = NULL;
    if (source == NULL || count == 0) {
        return NULL;
    }

    destination = (char**)malloc(count * sizeof(char*));
    if (destination == NULL) {
        return NULL;
    }

    for (size_t i = 0; i < count; ++i) {
        if (source[i] == NULL) {
            for (size_t j = 0; j < i; ++j) {
                free(destination[j]);
            }
            free(destination);
            return NULL;
        }

        size_t len = strlen(source[i]) + 1;
        destination[i] = (char*)malloc(len);
        if (destination[i] == NULL) {
            for (size_t j = 0; j < i; ++j) {
                free(destination[j]);
            }
            free(destination);
            return NULL;
        }

        memcpy(destination[i], source[i], len);
    }

    return destination;
}
