    LEX_INVALID
} TokenType;

TokenType jslTokenFromString(const char *str, char *tokenStr, size_t tokenStrLen) {
    if (str == NULL || tokenStr == NULL || tokenStrLen <= 0) {
        return LEX_INVALID;
