    int* elements;
} ThreadVector;

void* allocate_thread_vector(size_t size) {
    if (size == 0) {
        return NULL;
    }

    ThreadVector* vector = (ThreadVector*)malloc(sizeof(ThreadVector));
    if (vector == NULL) {
        return NULL;
