    tcb = initial_block_init((ptr_t)alloc, dtv);
    arch_tls_tcb_init(tcb);
    tcb->dtv = dtv;
    tcb->base = alloc;

    *tcbp = tcb;
    return STATUS_SUCCESS;
}

