#include <stdlib.h>
#include <string.h>

#define MAX_NAME_LENGTH 100
#define MAX_CODE_LENGTH 20

typedef struct {
    char codice[MAX_CODE_LENGTH];
    char nome[MAX_NAME_LENGTH];
    int ore;
} Athlete;

void searchAthlete(Athlete athletes[], int size) {
    char codice[MAX_CODE_LENGTH];
    printf("Enter athlete code to search: ");
    scanf("%s", codice);
    for (int i = 0; i < size; i++) {
        if (strcmp(athletes[i].codice, codice) == 0) {
            printf("Athlete found: %s (%s) - Hours: %d\n", athletes[i].nome, athletes[i].codice, athletes[i].ore);
            return;
        }
    }
    printf("Athlete not found.\n");
}

void addAthlete(Athlete athletes[], int *size) {
    if (*size >= 100) {
        printf("Database is full, cannot add more athletes.\n");
        return;
    }
    printf("Enter athlete code: ");
    scanf("%s", athletes[*size].codice);
    printf("Enter athlete name: ");
    scanf("%s", athletes[*size].nome);
    athletes[*size].ore = 0;
    (*size)++;
    printf("Athlete added successfully.\n");
}

void updateHours(Athlete athletes[], int size) {
    char codice[MAX_CODE_LENGTH];
    int newOre;
    printf("Enter athlete code to update hours: ");
