    for (int i = 0; i < size; i++) {
        if (strcmp(athletes[i].codice, codice) == 0) {
            athletes[i].ore = newOre;
            printf("Hours updated successfully.\n");
            return;
        }
    }
    printf("Athlete not found.\n");
}

