static PyObject *ndarray_get_axis_elements(PyObject *self, PyObject *args) {
    PyArrayObject *arr;
    int axis;
    if (!PyArg_ParseTuple(args, "Oi", &arr, &axis)) {
        return NULL;
    }

    int nd = PyArray_NDIM(arr);
