#include <stdlib.h>
#include <string.h>

char* modify_and_append_newline(char* input) {
    if (input == NULL) {
        return NULL;
    }

    size_t len = strlen(input);
    if (len == 0) {
        return input;
    }

    // Remove trailing newlines and carriage returns
    while (len > 0 && (input[len - 1] == '\n' || input[len - 1] == '\r')) {
        input[len - 1] = '\0';
        len--;
    }

    // Append a newline character
    input[len] = '\n';
    input[len + 1] = '\0';

    return input;
}
