#include <stdio.h>
#include <dirent.h>
#include <string.h>
#include <stdlib.h>

typedef void (*file_callback)(const char *path, void *usr);

int isSafePath(const char *base, const char *path) {
    if (strncmp(path, base, strlen(base)) != 0) {
        return 0;
    }
    return 1;
}

int doTraversal(const char *path, int recursive, file_callback xCallback, void *usr) {
    DIR *pdir;
    struct dirent *entry;
    pdir = opendir(path);
    if (pdir == NULL) {
        fprintf(stderr, "opendir error:%s\n", path);
        return 1;
    }

    while ((entry = readdir(pdir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;

        char full_path[256];
        snprintf(full_path, sizeof(full_path), "%s/%s", path, entry->d_name);

        if (!isSafePath(path, full_path)) {
            fprintf(stderr, "Access denied: %s\n", full_path);
            continue;
        }

        if (entry->d_type == DT_DIR) {
            if (recursive) {
                doTraversal(full_path, recursive, xCallback, usr);
            }
        } else {
            xCallback(full_path, usr);
        }
