#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define HASH_SIZE 1024
#define MAX_KEY_LENGTH 128

typedef struct pair {
    char key[MAX_KEY_LENGTH];
    char value[MAX_KEY_LENGTH];
    bool active;
} pair_t;

typedef struct bucket {
    pair_t pairs[HASH_SIZE];
} bucket_t;

typedef struct hashtable {
    bucket_t buckets[HASH_SIZE];
} hashtable_t;

size_t hash_str(const char *str) {
    size_t hash = 0;
    while (*str) {
        hash = (hash * 31) + *str;
        str++;
    }
    return hash;
}

pair_t *hashtable_find_pair(hashtable_t *hashtable, bucket_t *bucket, const char *key, size_t hash) {
    for (int i = 0; i < HASH_SIZE; i++) {
        if (bucket->pairs[i].active && strcmp(bucket->pairs[i].key, key) == 0) {
            return &bucket->pairs[i];
        }
    }
    return NULL;
}

int hashtable_get(hashtable_t *hashtable, const char *key, char *value) {
    size_t hash = hash_str(key);
    bucket_t *bucket = &hashtable->buckets[hash & (HASH_SIZE - 1)];
    pair_t *pair = hashtable_find_pair(hashtable, bucket, key, hash);

    if (pair && pair->active) {
        strcpy(value, pair->value);
        return 0; // No collisions
    } else {
        return -1; // Key not found or not active
    }
}

