import java.security.SecureRandom;
import java.util.Base64;

public class PasswordGenerator {

    public static String generatePassword(int length, String endCharacters) throws NoSuchAlgorithmException {
        if (length <= 0 || endCharacters == null || endCharacters.isEmpty()) {
            throw new IllegalArgumentException("Invalid input parameters.");
        }

        SecureRandom secureRandom = SecureRandom.getInstanceStrong();
        StringBuilder password = new StringBuilder();

        // Generate a random base password
        for (int i = 0; i < length - endCharacters.length(); i++) {
            password.append((char) (secureRandom.nextInt(94) + 33)); // ASCII printable characters
