import java.util.ArrayList;
import java.util.List;
import java.util.Random;

public class PairProcessor {
    private List<Pair> pairs;
    private Random random;

    public PairProcessor(List<Pair> pairs) {
        this.pairs = new ArrayList<>(pairs);
        this.random = new Random();
    }

    public void processPairs(int percentage) {
        int size = pairs.size();
        int targetSize = (int) (size * percentage);
        int processed = 0;

        while (processed < targetSize) {
            int currentIndex = pairs.size() - 1;
            Pair currentPair = pairs.get(currentIndex);

            if (currentIndex == 0) {
                System.out.println("Current pair is the last one.");
            } else {
                int previousIndex = random.nextInt(currentIndex);
                Pair previousPair = pairs.get(previousIndex);

                pairs.set(previousIndex, currentPair);
                pairs.set(currentIndex, previousPair);

                System.out.println("Moved pair " + currentIndex + " to position " + previousIndex);
            }

            processed++;
        }
    }

    public static void main(String[] args) {
        List<Pair> pairs = new ArrayList<>();
        pairs.add(new Pair(10, true));
        pairs.add(new Pair(20, false));
        pairs.add(new Pair(30, true));
        pairs.add(new Pair(40, false));

        PairProcessor processor = new PairProcessor(pairs);
        processor.processPairs(0.5);
    }
}

