import java.io.File;
import java.io.IOException;
import java.net.URISyntaxException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;

import com.google.common.base.Joiner;

public class KeystoreGenerator {

    public static void main(String[] args) {
        try {
            generateKeystore("example.com", "365", "password123");
        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        }
    }

    private static void generateKeystore(String hostname, String validity, String sslPass) throws IOException, InterruptedException {
        String canonicalWebUrl = "https://" + hostname;
        String url = canonicalWebUrl;
        if (url == null || url.isEmpty()) {
            url = canonicalWebUrl;
        }
        String sanitizedHostname = hostname;

        File store = new File("keystore.jks");
        if (!store.exists()) {
            createKeystore(store, sanitizedHostname, sslPass, validity);
        }
    }

    private static void createKeystore(File store, String hostname, String sslPass, String validity) throws IOException, InterruptedException {
        File tmpdir = Files.createTempDirectory("tmp.sslcertgen").toFile();
        chmod(0700, tmpdir);

        File tmpstore = new File(tmpdir, "keystore.jks");
        ProcessBuilder processBuilder = new ProcessBuilder(
            "keytool", 
            "-keystore", tmpstore.getAbsolutePath(), 
            "-storepass", sslPass, 
            "-genkeypair", 
            "-alias", hostname, 
            "-keyalg", "RSA", 
            "-validity", validity, 
            "-dname", "CN=" + hostname + ",OU=Gerrit Code Review,O=" + getDomain(hostname), 
            "-keypass", sslPass
        );

        Process process = processBuilder.directory(tmpdir).start();
        int exitCode = process.waitFor();
        if (exitCode != 0) {
            throw new IOException("Failed to create keystore");
        }

        if (!tmpstore.renameTo(store)) {
            throw new IOException("Cannot rename " + tmpstore + " to " + store);
        }
        if (!tmpdir.delete()) {
            throw new IOException("Cannot delete " + tmpdir);
        }
    }

    private static String getDomain(String hostname) {
        int index = hostname.indexOf('.');
        if (index != -1) {
            return hostname.substring(index + 1);
        }
        return "Unknown";
    }

    private static void chmod(int mode, File file) throws IOException {
        if (!file.setExecutable((mode & 0100) != 0, false) ||
            !file.setReadable((mode & 0040) != 0, false) ||
            !file.setWritable((mode & 0020) != 0, false)) {
            throw new IOException("Failed to set permissions on " + file);
        }
    }
}
