def evaluate_lock_definition(lock_definition, functions):
    locks = {}
    duplicates = 0
    wlist = []  # warnings
    try:
        access_type, rhs = (part.strip() for part in lock_definition.split(':', 1))
    except ValueError:
        raise ValueError("Invalid lock definition format")

    funclist = _RE_FUNCS.findall(rhs)
    evalstring = rhs
    for pattern in ('AND', 'OR', 'NOT'):
        evalstring = re.sub(r"\b%s\b" % pattern, pattern.lower(), evalstring)

    nfuncs = len(funclist)
    for funcstring in funclist:
        funcname, rest = (part.strip().strip(')') for part in funcstring.split('(', 1))
        func = next((f for f, args, kwargs in functions if f.__name__ == funcname), None)
        if not func:
            raise ValueError(f"Lock function '{funcname}' is not available")

        args = list(arg.strip() for arg in rest.split(',') if arg and not '=' in arg)
        kwargs = dict([arg.split('=', 1) for arg in rest.split(',') if arg and '=' in arg])
        lock_funcs.append((func, args, kwargs))
        evalstring = evalstring.replace(funcstring, '%s')

    if len(lock_funcs) < nfuncs:
        raise ValueError("Syntax error in lock definition")

    try:
        evalstring = " ".join(_RE_OK.findall(evalstring))
        evaluated_result = eval(evalstring % tuple(func for func in lock_funcs), {}, {})
    except Exception as e:
        raise ValueError(f"Syntax error in lock definition: {e}")

    if access_type in locks:
        duplicates += 1
        wlist.append(f"Access type '{access_type}' changed from '{locks[access_type][2]}' to '{lock_definition}'")

    locks[access_type] = (evaluated_result, tuple(lock_funcs), lock_definition)

    if wlist:
        logger.log_file("\n".join(wlist), WARNING_LOG)

    return locks[access_type]
