import pickle
from typing import Iterator, Optional

class FileReader:
    def __init__(self, file_path: str, buffer_size: int = 1024, _account_id: Optional[str] = None, delimiter: str = '\n', fail_on_missing_input: bool = False):
        self.file_path = file_path
        self.buffer_size = buffer_size
        self._account_id = _account_id
        self.delimiter = delimiter
        self._fail_on_missing_input = fail_on_missing_input
        self._bucket_iter = None
        self._bucket = self._load_bucket()

    def _load_bucket(self) -> Iterator:
        try:
            with open(self.file_path, 'r', encoding='utf-8') as file:
                while True:
                    data = file.read(self.buffer_size)
                    if not data:
                        break
                    yield data
        except FileNotFoundError:
            if self._fail_on_missing_input:
                raise
            else:
                yield ''

    def __iter__(self):
        if self._bucket_iter is None:
            self._bucket_iter = iter(self._bucket)
        return self

    def __next__(self):
        return next(self._bucket_iter)

    @classmethod
    def from_json(cls, state: dict):
        obj = pickle.loads(state[cls._JSON_PICKLE])
        # fail_on_missing_input might not be set - default to False.
        obj._fail_on_missing_input = state.get(cls._JSON_FAIL_ON_MISSING_INPUT, False)
        if obj._bucket:
            obj._bucket_iter = iter(obj._bucket)
        return obj

    def to_json(self):
        state = {
            self._JSON_PICKLE: pickle.dumps(self),
            self._JSON_FAIL_ON_MISSING_INPUT: self._fail_on_missing_input
        }
        return json.dumps(state)

    _JSON_PICKLE = 'pickle'
    _JSON_FAIL_ON_MISSING_INPUT = 'fail_on_missing_input'
